<?php

declare(strict_types=1);

namespace Domain\Plans\Calls;

use App\Actors\Enums\ActorType;
use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use Domain\Plans\Enums\PlanType;
use Domain\Plans\Http\Data\AssignedPlanListData;
use Domain\Plans\Http\Data\PlanWorkResultData;

/**
 * The signed calls of Plans, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class PlanCalls
{
    public function __construct(private CallSender $sender) {}

    public function addPhase(
        string $planId,
        string $title,
        CallKey $requestKey = new CallKey(),
    ): PhaseNamed {
        return $this->sender->send(AddPhaseCall::from([
            'planId' => $planId,
            'title' => $title,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $taskIds
     */
    public function addPhaseTasks(
        string $phaseId,
        int $expectedRevision,
        array $taskIds,
        CallKey $requestKey = new CallKey(),
    ): PhaseTasksAdded {
        return $this->sender->send(AddPhaseTasksCall::from([
            'phaseId' => $phaseId,
            'expectedRevision' => $expectedRevision,
            'taskIds' => $taskIds,
            'requestKey' => $requestKey,
        ]));
    }

    public function assignPlanWork(
        string $rootType,
        string $rootId,
        ActorType $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
        string|null $rootPlan = null,
    ): PlanWorkResultData {
        return $this->sender->send(AssignPlanWorkCall::from([
            'rootType' => $rootType,
            'rootId' => $rootId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
            'rootPlan' => $rootPlan,
        ]));
    }

    public function cancelPlan(
        string $planId,
        int $expectedRevision,
        string $reason,
        CallKey $requestKey = new CallKey(),
    ): PlanNamed {
        return $this->sender->send(CancelPlanCall::from([
            'planId' => $planId,
            'expectedRevision' => $expectedRevision,
            'reason' => $reason,
            'requestKey' => $requestKey,
        ]));
    }

    public function createPlan(
        string $title,
        string $brief,
        PlanType $type,
        CallKey $requestKey = new CallKey(),
    ): PlanNamed {
        return $this->sender->send(CreatePlanCall::from([
            'title' => $title,
            'brief' => $brief,
            'type' => $type,
            'requestKey' => $requestKey,
        ]));
    }

    public function editPlan(
        string $planId,
        int $expectedRevision,
        string|null $title,
        string|null $brief,
        PlanType|null $type,
        CallKey $requestKey = new CallKey(),
    ): PlanEdited {
        return $this->sender->send(EditPlanCall::from([
            'planId' => $planId,
            'expectedRevision' => $expectedRevision,
            'title' => $title,
            'brief' => $brief,
            'type' => $type,
            'requestKey' => $requestKey,
        ]));
    }

    public function finishPlan(
        string $planId,
        int $expectedRevision,
        string $note,
        CallKey $requestKey = new CallKey(),
    ): PlanNamed {
        return $this->sender->send(FinishPlanCall::from([
            'planId' => $planId,
            'expectedRevision' => $expectedRevision,
            'note' => $note,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $states
     */
    public function listAssignedPlans(
        string|null $search = null,
        array $states = [],
        int $page = 1,
        int $perPage = 20,
    ): AssignedPlanListData {
        return $this->sender->send(ListAssignedPlansCall::from([
            'search' => $search,
            'states' => $states,
            'page' => $page,
            'perPage' => $perPage,
        ]));
    }

    public function listPhaseChecks(
        int $plan,
        int $phase,
    ): PhaseChecks {
        return $this->sender->send(ListPhaseChecksCall::from([
            'plan' => $plan,
            'phase' => $phase,
        ]));
    }

    public function reassignPlanWork(
        string $rootType,
        string $rootId,
        string $assignmentId,
        ActorType $holderType,
        string $holderId,
        ActorType $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
        string|null $rootPlan = null,
    ): PlanWorkResultData {
        return $this->sender->send(ReassignPlanWorkCall::from([
            'rootType' => $rootType,
            'rootId' => $rootId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
            'rootPlan' => $rootPlan,
        ]));
    }

    public function recordPhaseCheck(
        int $plan,
        int $phase,
        string $receipt,
        CallKey $requestKey = new CallKey(),
    ): PhaseCheckRecorded {
        return $this->sender->send(RecordPhaseCheckCall::from([
            'plan' => $plan,
            'phase' => $phase,
            'receipt' => $receipt,
            'requestKey' => $requestKey,
        ]));
    }

    public function unassignPlanWork(
        string $rootType,
        string $rootId,
        string $assignmentId,
        ActorType $holderType,
        string $holderId,
        CallKey $requestKey = new CallKey(),
        string|null $rootPlan = null,
    ): PlanWorkResultData {
        return $this->sender->send(UnassignPlanWorkCall::from([
            'rootType' => $rootType,
            'rootId' => $rootId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'requestKey' => $requestKey,
            'rootPlan' => $rootPlan,
        ]));
    }
}
